head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = "330"; // 채권시장조치구분코드
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0; // 상세 조회 건수(0 이면 처리 버튼 동작 차단)
scwin.vViewYN = "N"; // 상세조회 보여주기 여부
scwin.vRowPos = 0; // 재조회 후 복원할 목록 행 위치(접수내역 탭)
scwin.vIsuCd = ""; // 선택 행 표준코드(종목코드)
scwin.hasAttachDoc = ""; // 선택 행 첨부문서 여부(Y/N)
scwin.gBndApplId = ""; // 선택 행 채권신청ID
scwin.gProcsStat = ""; // 선택 행 처리상태
scwin.processGp = ""; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6
scwin.empNo = ""; // 로그인 사번
scwin.empNm = ""; // 로그인 성명
scwin.jobtitl = ""; // 직위구분(팀장확인 권한 체크용)
scwin.duty = ""; // 직책 여부
scwin.dutyChrg = ""; // 직무대행 여부

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init(사용자 정보·탭 초기 상태) 후 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init();
        await scwin.listSync(); // 목록 조회
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 세션 사용자 정보 보관, 신청내역 탭 선택, 탭별 버튼 표시·입력필드 ReadOnly 설정
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.empNo = $c.session.getUserInfo("empNo"); // 사원번호
    scwin.empNm = $c.session.getUserInfo("empNm"); // 사용자이름
    scwin.jobtitl = $c.session.getUserInfo("jobtitl");
    scwin.duty = $c.session.getUserInfo("duty");
    scwin.dutyChrg = $c.session.getUserInfo("dutyChrg");

    tab_List.setSelectedTabIndex(0);
    scwin.vBndListProcsTpCd = 1;
    scwin.setTabButtons(scwin.vBndListProcsTpCd); // 탭별 버튼 표시
    scwin.chgTabAct(scwin.vBndListProcsTpCd); // 필드 ReadOnly 속성 제거/부여
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_ontabclick
 * @description 신청내역/접수내역 탭 클릭 — 처리구분 변경, 탭별 버튼·ReadOnly 갱신 후 목록 재조회
 * @param {String} tabId 탭 id
 * @param {Number} index 탭 index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_List_ontabclick = async function (tabId, index) {
    try {
        scwin.vBndListProcsTpCd = index + 1;
        scwin.vRowPos = 0;
        scwin.setTabButtons(scwin.vBndListProcsTpCd); // 탭별 버튼 표시
        scwin.chgTabAct(scwin.vBndListProcsTpCd); // 필드 ReadOnly 속성 제거/부여
        await scwin.listSync(); // 목록 조회
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.tab_List_ontabclick" });
    }
};

/**
 * @method
 * @name grd_List1_oncellclick
 * @description 신청내역 그리드 셀 클릭 — 선택 행 상세 조회
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List1_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.selectRow(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.grd_List1_oncellclick" });
    }
};

/**
 * @method
 * @name grd_List2_oncellclick
 * @description 접수내역 그리드 셀 클릭 — 선택 행 상세 조회
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.selectRow(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.grd_List2_oncellclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 조회(신청내역 탭) — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description 접수 — 「접수」 클릭 이벤트(신청데이터 접수 처리)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "1";
        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Acpt_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret_onclick
 * @description 반송(신청내역 탭) — 「반송」 클릭 이벤트(반송처리 팝업 호출)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Ret_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "2";
        await scwin.openReturnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Ret_onclick" });
    }
};

/**
 * @method
 * @name btn_Search2_onclick
 * @description 조회(접수내역 탭) — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search2_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Search2_onclick" });
    }
};

/**
 * @method
 * @name btn_ApprovFileCreat_onclick
 * @description 결재파일생성 — 「결재파일생성」 클릭 이벤트(결재파일 생성 팝업 ULDBNS90005 호출)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApprovFileCreat_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;

        const options = {
            id : "ULDBNS90005",
            popupName : "결재파일 생성",
            frameModal : "top",
            width : "600px",
            height : "500px"
        };
        await $c.win.openPopup("/ui/bns/bnscommon/ULDBNS90005.xml", options, scwin.getParApprovFileWrt());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name btn_Proc_onclick
 * @description 처리완료 — 「처리완료」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Proc_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "3";
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Proc_onclick" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 수정 — 「수정」 클릭 이벤트(접수 후 수정 처리)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "4";
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 팀장확인 — 「팀장확인」 클릭 이벤트(공통 체크 후 팀장확인 처리)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function (e) {
    try {
        // 현업요청으로 팀장확인 추가 jackal_140804
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "6";

        // 접수, 처리완료 공통 체크
        if (await scwin.acptProcsCheck() > 0) return;
        const confrmDd = dlt_searchList.getCellData(scwin.vRowPos, "teamleaderConfrmDd");
        await scwin.teamleadrConfrm1(confrmDd, scwin.gBndApplId, scwin.vBndListProcsTpCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_TeamleadrConfrm_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret2_onclick
 * @description 반송(접수내역 탭) — 「반송」 클릭 이벤트(수정/반송 가능 여부 체크 후 반송처리 팝업 호출)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Ret2_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        // 접수 후 수정 및 반송시 체크한다.
        if (await scwin.checkModAndRet(scwin.gBndApplId) > 0) return;
        scwin.processGp = "2";
        await scwin.openReturnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Ret2_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach_onclick
 * @description 첨부파일확인 — 「첨부파일확인」 클릭 이벤트(첨부문서 검색 팝업 ULDBNS90001 호출)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if (dma_detail.get("hasAttachDoc") === "N") {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }

        const options = {
            id : "ULDBNS90001",
            popupName : "첨부문서 검색",
            frameModal : "top",
            width : "600px",
            height : "500px"
        };
        await $c.win.openPopup("/ui/bns/bnscommon/ULDBNS90001.xml", options, scwin.getCommonKey());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name btn_Dtl_onclick
 * @description 종목상세내역 — 「종목상세내역」 클릭 이벤트(종목 상세정보 조회 팝업 ULDBNS25102 호출)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Dtl_onclick = async function (e) {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;

        const options = {
            id : "ULDBNS25102",
            popupName : "종목 상세정보 조회",
            frameModal : "top",
            width : "600px",
            height : "500px"
        };
        await $c.win.openPopup("/ui/bns/bnslistsrchl/ULDBNS25102.xml", options, scwin.getParIsuDelInfo());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS15600.btn_Dtl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록조회 — 탭의 처리구분(신청/접수) 기준으로 WIT종목정보확정 신청·접수 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd);
    dma_search.set("vMktactCd", scwin.vMktactCd);

    const sbmOptions = {
        id : "sbm_searchList",
        action : "/api/bonds/bndNew/WITStockConf/WITStockConfApplAcpt-select",
        method : "get",
        ref : "dma_search=body",
        target : "dlt_searchList=body",
        gridview : "grd_List1,grd_List2",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_searchList_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_searchList_submitdone
 * @description 목록 조회 후처리 — 접수내역 탭은 처리(접수·수정·처리완료·팀장확인) 전 행으로 복원, 그 외 첫 행 선택 후 상세 조회. 결과 없으면 상세 초기화
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_searchList_submitdone = async function (e) {
    if (e && e.skipped) return; // 중복 제출 skip 응답은 무시

    if (e.responseStatusCode !== 200) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }

    const rowCount = dlt_searchList.getRowCount();
    if (rowCount === 0) {
        dma_detail.setEmptyValue();
        scwin.vDtlInfoRowCount = 0;
        scwin.gBndApplId = "";
        scwin.gProcsStat = "";
        scwin.procBtnStat();
        return;
    }

    // 접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
    let row = (scwin.vBndListProcsTpCd === 2) ? scwin.vRowPos : 0;
    if (row < 0 || row >= rowCount) row = 0;
    dlt_searchList.setRowPosition(row);
    await scwin.selectRow(row);
};

/**
 * @method
 * @name dtlSync
 * @description 상세조회 — 선택 행의 WIT종목정보확정 상세 조회
 * @param {Object} dtlJson 선택 행 JSON(bndMktactTpCd, bndApplId)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dtlSync = async function (dtlJson) {
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd);
    dma_search.set("vMktactCd", dtlJson.bndMktactTpCd);
    dma_search.set("vBndApplId", dtlJson.bndApplId);
    dma_search.set("vViewYn", scwin.vViewYN);

    const sbmOptions = {
        id : "sbm_detail",
        action : "/api/bonds/bndNew/WITStockConf/WITStockConfDetail-select",
        method : "get",
        ref : "dma_search=body",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_detail_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_detail_submitdone
 * @description 상세 조회 후처리 — 상세 건수(채권신청ID 유무) 보관, 실패 시 오류 알림
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_detail_submitdone = async function (e) {
    if (e && e.skipped) return; // 중복 제출 skip 응답은 무시

    if (e.responseStatusCode === 200) {
        scwin.vDtlInfoRowCount = $c.util.isEmpty(dma_detail.get("bndApplId")) ? 0 : 1;
    } else {
        scwin.vDtlInfoRowCount = 0;
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

/**
 * @method
 * @name getCheckUrl
 * @description 접수·처리완료·수정 시 체크항목(적용일·매매일·마감·채권마감)을 조회한다
 * @param {String} strtDd 적용일(상장일)
 * @param {String} bndApplId 채권신청ID
 * @param {String} stdCdYn 표준코드 체크 여부(Y/N)
 * @returns {Promise<Object>} 통신 응답 객체(resObj)
 * @hidden N
 */
scwin.getCheckUrl = async function (strtDd, bndApplId, stdCdYn) {
    dma_getCheckUrl.set("vBndApplId", bndApplId);
    dma_getCheckUrl.set("vStrtDd", strtDd);
    dma_getCheckUrl.set("vStdCdYn", stdCdYn);

    const sbmOptions = {
        id : "sbm_getCheckUrl",
        action : "/api/bonds/bndCommon/itemOfApplAcptAndCls-chk",
        method : "get",
        ref : "dma_getCheckUrl=body",
        target : "dma_rtnGetCheckUrl=body",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    return sbmRtn;
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다 — 공통 체크·첨부문서 확인·복수조치 체크 후 접수 전송
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function () {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 첨부문서 체크
    if (!(await $c.bns.endConfirm(scwin.hasAttachDoc, "접수"))) return;

    // 복수조치 체크
    if (await scwin.checkMultActImpsblRule(scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    dma_Param.set("empNo", scwin.empNo);
    dma_Param.set("empNm", scwin.empNm);
    dma_Param.set("mktactTpCd", scwin.vMktactCd);
    dma_Param.set("regYn", "N");

    const sbmOptions = {
        id : "sbm_WITStockConfAppl",
        action : "/api/bonds/bndNew/WITStockConf/WITStockConfAppl-proc",
        method : "post",
        ref : "dma_Param=dts_Param,dma_detail=dts_DtlInfo_WITStockConf",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_save_submitdone(sbmRtn);
};

/**
 * @method
 * @name checkMultActImpsblRule
 * @description 해당종목의 복수조치 건이 접수되어 있는지 체크
 * @param {String} vIsuCd 표준코드(종목코드)
 * @param {String} vMktactCd 채권시장조치구분코드
 * @param {String} vStrtDd 적용일
 * @returns {Promise<Number>} 0: 진행, 1: 중단
 * @hidden N
 */
scwin.checkMultActImpsblRule = async function (vIsuCd, vMktactCd, vStrtDd) {
    dma_chkMltActImpsbl.set("vIsuCd", vIsuCd);
    dma_chkMltActImpsbl.set("vMktactCd", vMktactCd);
    dma_chkMltActImpsbl.set("vStrtDd", vStrtDd);

    const sbmOptions = {
        id : "sbm_checkMultActImpsblRule",
        action : "/api/bonds/bndCommon/multActImpsblRule-chk",
        method : "get",
        ref : "dma_chkMltActImpsbl=body",
        target : "dma_rtnChkMltActImpsbl=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions);

    if (dma_rtnChkMltActImpsbl.get("MULTACT_IMPSBL_CNT") > 0) {
        await $c.win.alert(scwin.getMultActImpsblMsg());
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다 — 마이너스 금리·공통·복수조치 체크 통과 후 처리구분(4: 수정, 그 외: 처리완료)별 전송
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function () {
    // 마이너스 금리 체크 (처리완료 및 수정만 체크토록 수정) JACKAL_191129
    if (await scwin.minusGumriCheck() > 0) return;

    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 복수조치 체크
    if (await scwin.checkMultActImpsblRuleProcEnd(scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    dma_Param.set("empNo", scwin.empNo);
    dma_Param.set("empNm", scwin.empNm);
    dma_Param.set("mktactTpCd", scwin.vMktactCd);

    let url = "";
    if (scwin.processGp === "4") {
        // 접수 후 수정 및 반송시 체크한다.
        if (await scwin.checkModAndRet(scwin.gBndApplId) > 0) return;
        if (!(await $c.win.confirm("수정처리 하시겠습니까?"))) return;
        url = "/api/bonds/bndNew/WITStockConf/WITStockConfAcpt-modify";
    } else {
        await $c.win.alert("표준코드시스템에서 표면이자율을 업데이트하여 주시기 바랍니다.");
        // 첨부문서 체크
        if (!(await $c.bns.endConfirm(scwin.hasAttachDoc, "처리완료"))) return;
        url = "/api/bonds/bndNew/WITStockConf/WITStockConfAcpt-procComplt";
    }

    const sbmOptions = {
        id : "sbm_WITStockConfModifyComplt",
        action : url,
        method : "post",
        ref : "dma_Param=dts_Param,dma_detail=dts_DtlInfo_WITStockConf",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_save_submitdone(sbmRtn);
};

/**
 * @method
 * @name checkMultActImpsblRuleProcEnd
 * @description 해당종목의 복수조치 건이 처리완료 되어 있는지 체크
 * @param {String} vIsuCd 표준코드(종목코드)
 * @param {String} vMktactCd 채권시장조치구분코드
