/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다 — 공통 검증(validateDataCollect)으로 상장일(필수·날짜)·한글/영문고유명·변경후 표면이자율/낙찰금리/발행금액/상장금액(필수) 검증, 스트립대상(stripObjYn=Y)이면 스트립미분리잔액도 필수
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.inputCheck = async function () {
    const fields = {
        edt_StrtDd : { required : true, format : "date", name : "상장일" },
        txb_UnqIsuNm : { required : true, name : "한글고유명" },
        txb_UnqIsuEngNm : { required : true, name : "영문고유명" },
        edt_CpnIntRt : { required : true, name : "변경후 표면이자율" },
        edt_ScbdInt : { required : true, name : "변경후 낙찰금리" },
        edt_IsuAmt : { required : true, name : "변경후 발행금액" },
        edt_ListAmt : { required : true, name : "변경후 상장금액" }
    };
    if (dma_detail.get("stripObjYn") === "Y") {
        fields.edt_StripNsprtBal = { required : true, name : "스트립미분리잔액" };
    }
    return $c.validate.validateDataCollect(pnl_DtlInfo, { fields : fields });
};

/**
 * @method
 * @name unqIsuNmCheck
 * @description 고유명 연번호 체크 — 한글/영문고유명이 '00000-YYMM(YY-0)' 형식인지 확인해 안내한다(AS-IS 규약: 안내·포커스만 하고 처리는 계속)
 * @returns {Promise<Boolean>} 항상 true(AS-IS 의 return false 주석 상태 유지)
 * @hidden N
 */
scwin.unqIsuNmCheck = async function () {
    await scwin.checkUnqIsuNmFormat(txb_UnqIsuNm, "한글고유명");
    await scwin.checkUnqIsuNmFormat(txb_UnqIsuEngNm, "영문고유명");
    return true;
};

/**
 * @method
 * @name checkUnqIsuNmFormat
 * @description 고유명 연번호 형식 검사 — '00000-YYMM(YY-0)'(5자리-7자리(괄호 포함)-2~3자리) 형식이 아니면 안내 후 포커스
 * @param {Object} comp 고유명 입력 컴포넌트
 * @param {String} label 항목명(한글고유명/영문고유명)
 * @returns {Promise<Boolean>} 형식 적합 여부
 * @hidden N
 */
scwin.checkUnqIsuNmFormat = async function (comp, label) {
    const parts = comp.getValue().split("-");
    const valid = parts.length === 3
        && parts[0].length === 5
        && parts[1].length === 7 && parts[1].indexOf("(") > -1
        && (parts[2].length === 2 || parts[2].length === 3) && parts[2].indexOf(")") > -1;
    if (!valid) {
        await $c.win.alert(label + " 연번호를 확인하시기 바랍니다.\n\n고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        comp.focus();
    }
    return valid;
};

/**
 * @method
 * @name minusGumriOK
 * @description 마이너스 금리 입력 확인 — 음수이면 그대로 처리할지 확인한다 JACKAL_191129
 * @param {Object} obj 금리 입력 컴포넌트
 * @param {String} msg 항목명
 * @returns {Promise<Boolean>} true: 진행, false: 중단
 * @hidden N
 */
scwin.minusGumriOK = async function (obj, msg) {
    const objRt = obj.getValue();
    if (objRt < 0) {
        if (!(await $c.win.confirm("[" + msg + "] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?"))) {
            obj.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name minusGumriCheck
 * @description 마이너스 금리 일괄 체크 — 변경후 표면이자율·낙찰금리 JACKAL_191129
 * @returns {Promise<Number>} 0: 진행, 1: 중단
 * @hidden N
 */
scwin.minusGumriCheck = async function () {
    if (!(await scwin.minusGumriOK(edt_CpnIntRt, "변경후 표면이자율"))) return 1;
    if (!(await scwin.minusGumriOK(edt_ScbdInt, "낙찰금리"))) return 1;
    return 0;
};

/**
 * @method
 * @name acptProcsCheck
 * @description 접수, 처리완료시 공통 체크 구문 — 필수값·고유명 연번호(접수내역 탭)·적용일 관련 체크 후 종목코드·첨부문서 여부 보관
 * @returns {Promise<Number>} 0: 진행, 1: 중단
 * @hidden N
 */
scwin.acptProcsCheck = async function () {
    // 필수입력값 체크
    if (!(await scwin.inputCheck())) return 1;

    // 고유명 연번호 체크
    if (scwin.vBndListProcsTpCd === 2) {
        if (!(await scwin.unqIsuNmCheck())) return 1;
    }

    // 적용일,매매일,마감일,채권마감 체크
    if (await scwin.checkCmData(edt_StrtDd.getValue(), scwin.gBndApplId) > 0) return 1;

    scwin.vIsuCd = dma_detail.get("isuCd");
    scwin.hasAttachDoc = dma_detail.get("hasAttachDoc");

    return 0;
};

/**
 * @method
 * @name checkCmData
 * @description 월별 접수·처리완료·수정 시 체크항목 — 서버 체크 응답 플래그(dma_rtnGetCheckUrl)를 공통 검증(validateDataMap)으로 순서대로 검사
 * @param {String} strtDd 적용일(상장일)
 * @param {String} bndApplId 채권신청ID
 * @returns {Promise<Number>} 0: 진행, 1~4: 중단 사유 코드
 * @hidden N
 */
scwin.checkCmData = async function (strtDd, bndApplId) {
    await scwin.getCheckUrl(strtDd, bndApplId, "N");

    return $c.validate.validateDataMap(dma_rtnGetCheckUrl, [
        { key : "VALID_STRT_DD", equals : "Y", message : "적용일이 현재일자보다 작습니다. 다시 입력하십시오.", code : 1 },
        { key : "VALID_CALND_DD", equals : "Y", message : "적용일이 매매일에 유효하지 않습니다. 다시 입력하십시오.", code : 2 },
        // 적용일 전날이 아니면 확인메시지 보여주기(확인 시 다음 규칙 계속)
        { key : "VALID_BF_DD", equals : "Y", type : "confirm", message : "상장일/적용일이 익영업일이 아닙니다. 처리하시겠습니까?", code : 4 },
        { key : "VALID_CLS_DD", equals : "Y", message : "입력한 일자는 이미 마감처리가 종료된 일자입니다. 다시 입력하십시오.", code : 3 }
    ]);
};

/**
 * @method
 * @name checkModAndRet
 * @description 접수 후 수정 및 반송 가능 여부를 체크한다 — 서버 체크 응답 플래그(VALID_BND)를 공통 검증(validateDataMap)으로 검사
 * @param {String} bndApplId 채권신청ID
 * @returns {Promise<Number>} 0: 진행, 4: 중단(마감처리 종목)
 * @hidden N
 */
scwin.checkModAndRet = async function (bndApplId) {
