 * @method
 * @name procBtnStat
 * @description 처리 상태가 처리완료일 경우 처리완료 버튼 비활성화·팀장확인 버튼 활성화, 그 외는 반대
 * @returns {void}
 * @hidden N
 */
scwin.procBtnStat = function () {
    const isProcsDone = (scwin.gProcsStat === "처리완료");
    btn_Proc.setDisabled(isProcsDone);
    btn_TeamleadrConfrm.setDisabled(!isProcsDone);
};

/**
 * @method
 * @name setTabButtons
 * @description 탭별 상세 제목·버튼 표시 — 신청내역 탭은 조회/접수/반송, 접수내역 탭은 조회/결재파일생성/처리완료/수정/팀장확인/반송
 * @param {Number} vBndListProcsTpCd 채권처리구분(1:신청,2:접수)
 * @returns {void}
 * @hidden N
 */
scwin.setTabButtons = function (vBndListProcsTpCd) {
    const isAcpt = (vBndListProcsTpCd === 2);
    const reqButtons = [btn_Search, btn_Acpt, btn_Ret];
    const acptButtons = [btn_Search2, btn_ApprovFileCreat, btn_Proc, btn_Mod, btn_TeamleadrConfrm, btn_Ret2];

    txb_Dtl.setValue(isAcpt ? "WIT종목정보확정 접수내역" : "WIT종목정보확정 신청내역");
    reqButtons.forEach(function (btn) {
        if (isAcpt) btn.hide(); else btn.show();
    });
    acptButtons.forEach(function (btn) {
        if (isAcpt) btn.show(); else btn.hide();
    });
};

/**
 * @method
 * @name chgTabAct
 * @description 탭 전환 시 필드 ReadOnly/Disabled 속성 제거/부여 — 신청내역 탭은 변경후 항목 읽기전용, 접수내역 탭은 입력 가능(변경전 항목은 항상 비활성)
 * @param {Number} vBndListProcsTpCd 채권처리구분(1:신청,2:접수)
 * @returns {void}
 * @hidden N
 */
scwin.chgTabAct = function (vBndListProcsTpCd) {
    const isReadOnly = (vBndListProcsTpCd === 1);

    cmb_BfchgCoupnRtFinalYn.setDisabled(true);
    cmb_BfchgPresaleGovbndTrdTpCd.setDisabled(true);

    // 변경후 이자율, 고유명, 발행전국채거래구분, 금액
    cmb_CoupnRtFinalYn.setDisabled(isReadOnly);
    txb_UnqIsuNm.setDisabled(isReadOnly);
    txb_UnqIsuEngNm.setDisabled(isReadOnly);
    cmb_PresaleGovbndTrdTpCd.setDisabled(isReadOnly);
    edt_CpnIntRt.setReadOnly(isReadOnly);
    edt_ScbdInt.setReadOnly(isReadOnly);
    edt_IsuAmt.setReadOnly(isReadOnly);
    edt_ListAmt.setReadOnly(isReadOnly);
    edt_StripNsprtBal.setReadOnly(isReadOnly);
};
